import { render, screen, within } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

vi.mock('@capacitor/core', () => ({ Capacitor: { isNativePlatform: () => false } }))

import type { PhotoThumbLocal } from '../../data/photoThumbRepo'
import type { UpdateCycleLocal, UpdateCyclePhoto } from '../../data/updateCycleRepo'
import { BODYBUILDING_POSES } from '../../domain/questionnaireTemplate'
import { PhotosStep } from './PhotosStep'

// Fictitious ids; the thumbnails are a few generated bytes, never a real photo.
const CYCLE_ID = '00000000-0000-0000-0000-000000000001'
const FILE_OLD = '00000000-0000-0000-0000-0000000000f1'
const FILE_NEW = '00000000-0000-0000-0000-0000000000f2'
const THUMB = 'data:image/jpeg;base64,AAAA'

const cycle = (photos: UpdateCyclePhoto[]): UpdateCycleLocal => ({
  id: CYCLE_ID,
  protocolVersionId: '00000000-0000-0000-0000-0000000000aa',
  periodStart: '2026-10-01',
  periodEnd: '2026-10-23',
  status: 'draft',
  answers: {},
  photos,
  sentAt: null,
  clientUpdatedAt: '2026-10-19T10:00:00.000Z',
})

const thumb = (pose: string, fileId: string): PhotoThumbLocal => ({ fileId, cycleId: CYCLE_ID, pose, dataUrl: THUMB, createdAt: '2026-10-19T10:00:00.000Z' })

function renderStep(photos: UpdateCyclePhoto[], thumbs: PhotoThumbLocal[] = [], pending: string[] = []) {
  render(
    <PhotosStep
      cycle={cycle(photos)}
      poses={BODYBUILDING_POSES}
      thumbs={new Map(thumbs.map((t) => [t.pose, t]))}
      pending={new Set(pending)}
      overlayFor={() => Promise.resolve(null)}
      onCapture={() => Promise.resolve()}
      error={null}
    />,
  )
}

describe('PhotosStep', () => {
  it('one tile per bodybuilding pose, and no "Outras fotos" without photos of other poses', () => {
    renderStep([{ pose: 'front_double_biceps', fileId: FILE_NEW, takenAt: '2026-10-19T10:00:00.000Z' }])

    expect(screen.getByText('1 de 7 poses.', { exact: false })).toBeInTheDocument()
    for (const pose of BODYBUILDING_POSES) expect(screen.getByRole('listitem', { name: pose.label })).toBeInTheDocument()
    expect(screen.queryByRole('region', { name: 'Outras fotos' })).not.toBeInTheDocument()
  })

  it('a photo of a pose no longer in the list shows under "Outras fotos", only to see', () => {
    renderStep(
      [
        { pose: 'front', fileId: FILE_OLD, takenAt: '2026-10-18T10:00:00.000Z' },
        { pose: 'side_chest', fileId: FILE_NEW, takenAt: '2026-10-19T10:00:00.000Z' },
      ],
      [thumb('front', FILE_OLD), thumb('side_chest', FILE_NEW)],
      ['old_pose'],
    )

    // The counter only counts the poses of the list.
    expect(screen.getByText('1 de 7 poses.', { exact: false })).toBeInTheDocument()
    const others = screen.getByRole('region', { name: 'Outras fotos' })
    expect(within(others).getByText('Continuam no .zip das fotos.', { exact: false })).toBeInTheDocument()
    const front = within(others).getByRole('listitem', { name: 'Frente' })
    expect(within(front).getByRole('img', { name: 'Miniatura de Frente' })).toHaveAttribute('src', THUMB)
    expect(within(front).getByText('Enviada')).toBeInTheDocument()
    // No camera for a pose that left the list.
    expect(within(front).queryByRole('button')).not.toBeInTheDocument()
    // An unknown key still waiting in the queue shows with its key.
    expect(within(within(others).getByRole('listitem', { name: 'old_pose' })).getByText('Pendente de envio')).toBeInTheDocument()
    expect(within(others).getAllByRole('listitem')).toHaveLength(2)
    expect(within(others).queryByRole('listitem', { name: 'Peitoral de lado' })).not.toBeInTheDocument()
  })
})
